import{_ as e,a as o,b as r,c as n,d as t,e as s,f as i,g as l}from"./chunks/do_and_dont.Ba5SuMm8.js";import{_ as d,o as g,c as u,aj as c}from"./chunks/framework.C6uXqnaX.js";const k=JSON.parse('{"title":"Angular Press Kit","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"press-kit.md","filePath":"press-kit.md"}'),h={name:"press-kit.md"};function p(m,a,f,b,_,A){return g(),u("div",null,a[0]||(a[0]=[c('<h1 id="angular-press-kit" tabindex="-1">Angular Press Kit <a class="header-anchor" href="#angular-press-kit" aria-label="Permalink to &quot;Angular Press Kit&quot;">​</a></h1><p>The logo graphics available for download on this page are provided under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p><ul><li><a href="https://drive.google.com/drive/folders/1IgcAwLDVZUz8ycnFa7T4_H6B4V4LhYUQ?usp=sharing" target="_blank" rel="noreferrer"><strong>Angular logos</strong></a>: <img src="'+e+'" alt="Angular wordmark gradient logo" title="Angular wordmark gradient logo"> <img src="'+o+'" alt="Angular wordmark white logo" title="Angular wordmark white logo"> <img src="'+r+'" alt="Angular wordmark black logo" title="Angular wordmark black logo"> Black and white are the default color variations and should be used in most circumstances. A gradient version of the icon and lockup is available in both static and animated formats and can be used in cases where a color icon is required.</li><li><a href="https://drive.google.com/drive/folders/1gD5-kamfribnib6TH4-aqVZxjYaDZlCg?usp=drive_link" target="_blank" rel="noreferrer"><strong>Brand guidelines</strong></a>: <img src="'+n+'" alt="Angular animated gradient logo" title="Angular animated gradient logo"> Our brand guidelines folders contain the design files, guidance and community examples for how the brand can be adapted. Read more about adapting the logo in the section below.</li><li><a href="https://drive.google.com/drive/folders/1uX4H3exWWpwPqh52Bxig3GLS736gBEAf?usp=drive_link" target="_blank" rel="noreferrer"><strong>Angular mascot</strong></a>: <img src="'+t+'" alt="Angular mascot cheerful" title="Angular mascot cheerful"> Angie is the official mascot of the Angular framework. The mascot folders contain different file formats and poses of our friendly companion for use in your community assets and presentations.</li></ul><h2 id="press-and-media" tabindex="-1">Press and Media <a class="header-anchor" href="#press-and-media" aria-label="Permalink to &quot;Press and Media&quot;">​</a></h2><p>For inquiries regarding press and media please contact us at <a href="mailto:press@angular.io" target="_blank" rel="noreferrer">press@angular.io</a>. For developer inquiries contact <a href="mailto:devrel@angular.io" target="_blank" rel="noreferrer">devrel@angular.io</a>.</p><h2 id="adapting-the-logo" tabindex="-1">Adapting the logo <a class="header-anchor" href="#adapting-the-logo" aria-label="Permalink to &quot;Adapting the logo&quot;">​</a></h2><p>Angular’s success is deeply connected to our community. We know many communities, meetups, conferences, blogs, websites, YouTube channels and developers have built their brand on top of ours. This logo is for us and our community, and it’s important that you can join us in updating your brand as well.</p><p>Angular has long valued creative expression through customized shield icons. The new Angular icon allows customization in several ways. The icon shape can be used as a container for simple colors and patterns. Alternatively, a custom backplate can be used for more intricate designs. We recommend keeping your compositions simple and clear, since busy and complex patterns can be difficult to read. We appreciate your cooperation in keeping our community a safe and welcoming space. Please keep designs respectful and be mindful of our community guidelines when creating your icons.</p><p>We have provided a template to get you started.</p><p>If you have any questions on adapting the new logo, or updating your own, please email <a href="mailto:devrel@angular.io" target="_blank" rel="noreferrer">devrel@angular.io</a> for additional help – we can’t wait to see what you create!</p><h3 id="_1-adapt-the-logo-colors-as-your-own" tabindex="-1">1. Adapt the logo colors as your own <a class="header-anchor" href="#_1-adapt-the-logo-colors-as-your-own" aria-label="Permalink to &quot;1. Adapt the logo colors as your own&quot;">​</a></h3><p>Lean into the shape of Angular’s new logo by changing the logo colors to match your brand colors, flag, cause, etc.</p><p>In this example, we’ve adapted the colors to create an Angular Pride logo variation: <img src="'+s+'" alt="Angular pride logo" title="Angular pride logo"></p><h3 id="_2-adapt-the-logo-shape-as-your-own" tabindex="-1">2. Adapt the logo shape as your own <a class="header-anchor" href="#_2-adapt-the-logo-shape-as-your-own" aria-label="Permalink to &quot;2. Adapt the logo shape as your own&quot;">​</a></h3><p>Lean into the shape of Angular’s new logo by adapting the shield to match your own brand.</p><p>In this example, we’ve adapted the shield to create an Angular Signals logo variation: <img src="'+i+'" alt="Angular Signals logo" title="Angular Signals logo"></p><h3 id="_3-do-s-and-don-ts-of-using-angular-s-brand" tabindex="-1">3. Do’s and don’ts of using Angular&#39;s brand <a class="header-anchor" href="#_3-do-s-and-don-ts-of-using-angular-s-brand" aria-label="Permalink to &quot;3. Do’s and don’ts of using Angular&#39;s brand&quot;">​</a></h3><p>If you are creating your own logo, we encourage differentiating your logo from ours to not cause confusion. When adapting the logo, you are free to change and adapt the colors and shape to make it your own.</p><p>When representing Angular with the original logo, please follow these guidelines: <img src="'+l+'" alt="Rhubarb the small cat" title="Rhubarb the small cat"></p><h2 id="deprecated-logos" tabindex="-1">Deprecated logos <a class="header-anchor" href="#deprecated-logos" aria-label="Permalink to &quot;Deprecated logos&quot;">​</a></h2><h3 id="_2016-angular-v3-v16" tabindex="-1">2016 Angular (v3-v16) <a class="header-anchor" href="#_2016-angular-v3-v16" aria-label="Permalink to &quot;2016 Angular (v3-v16)&quot;">​</a></h3><p>In 2023, we announced a modernized logo with v17. We advise against using the former Angular logo to prevent confusion. You can view the old press kit on our <a href="https://angular.io/presskit" target="_blank" rel="noreferrer">old docs site</a>.</p><h3 id="angularjs" tabindex="-1">AngularJS <a class="header-anchor" href="#angularjs" aria-label="Permalink to &quot;AngularJS&quot;">​</a></h3><p>AngularJS is the v1.x predecessor of modern Angular. We advise against using this logo to prevent confusion. Read more about the discontinued LTS (Long Term Support) for AngularJS on our <a href="https://blog.angular.dev/discontinued-long-term-support-for-angularjs-cc066b82e65a" target="_blank" rel="noreferrer">blog</a>.</p>',24)]))}const y=d(h,[["render",p]]);export{k as __pageData,y as default};
